			if stdout.Len() != 0 {
				t.Errorf("Run(%s) wrote %q to stdout, want nothing", tt.name, stdout.String())
			}
			if n := bytes.Count(stderr.Bytes(), []byte("\n")); n != 1 {
				t.Errorf("Run(%s) wrote %d stderr lines, want 1", tt.name, n)
			}
		})
	}
