		{"2.675", "2.68"},
		{"-2.675", "-2.68"},
		{"1.005", "1.01"},
		{"10.125", "10.13"},
		{"-10.125", "-10.13"},
	}
	for _, tt := range tests {
		if got := Format(rat(t, tt.in)); got != tt.want {
			t.Errorf("Format(%s) = %q, want %q", tt.in, got, tt.want)
		}
	}
}

func TestFormatNeverWritesNegativeZero(t *testing.T) {
	for _, in := range []string{"0", "-0", "0.0", "-0.0", "-0.001", "-0.004"} {
