package infer

import (
	"regexp"
	"strings"
	"time"
)

// Type names written to the type field of a profile row.
const (
	Integer = "integer"
	Number  = "number"
	Date    = "date"
	Boolean = "boolean"
	Text    = "text"
	Empty   = "empty"
)

var (
	integerPattern = regexp.MustCompile(`^-?[0-9]+$`)
	numberPattern  = regexp.MustCompile(`^-?[0-9]+(\.[0-9]+)?$`)
	datePattern    = regexp.MustCompile(`^[0-9]{4}-[0-9]{2}-[0-9]{2}$`)
)

