def prof(columns, *opts):
    with tempfile.TemporaryDirectory() as d:
        path = write_table(d, columns)
        code, out, err = cli_runner(*opts, path)
    assert code == 0, (code, err)
    return {r["column"]: r for r in csv.DictReader(io.StringIO(out))}, out

def fmt2(fr):
    scaled = fr * 100; n, d = scaled.numerator, scaled.denominator
    r = (abs(n) * 2 + d) // (2 * d)
    sign = "-" if (n < 0 and r != 0) else ""
    return sign + str(r // 100) + "." + str(r % 100).zfill(2)

def median(vals):
    s = sorted(vals); m = len(s)
    return s[m // 2] if m % 2 else (s[m // 2 - 1] + s[m // 2]) / 2

NULLS = ("", "na", "n/a", "null")
def isnull(v): return v.strip().lower() in NULLS

